#!/usr/bin/env python3

"""A small task tracker."""

import sys


DEFAULT_PRIORITY = 5


class Task:
    def __init__(self, id, title):
        self.id = id
        self.title = title
        self.done = False
        self.priority = DEFAULT_PRIORITY


def find(tasks, id):
    for task in tasks:
        if task.id == id:
            return task
    return None


def by_priority(tasks):
    return sorted(tasks, key=lambda task: (task.priority, task.id))


def main():
    lines = open(sys.argv[1], "rb").read().decode("utf-8").rstrip("\n").split("\n")
    tasks = []
    next_id = 1

    for line in lines:
        if line.strip() == "":
            continue
        parts = line.split(" ", 1)
        command = parts[0]
        rest = parts[1] if len(parts) > 1 else ""

        if command == "add":
            tasks.append(Task(next_id, rest))
            print(f"added {next_id}")
            next_id = next_id + 1
        elif command == "done":
            id = int(rest)
            task = find(tasks, id)
            if task is None:
                print(f"no such task {id}")
            else:
                task.done = True
                print(f"done {id}")
        elif command == "prio":
            args = rest.split()
            id_text = args[0] if len(args) > 0 else ""
            p_text = args[1] if len(args) > 1 else ""
            try:
                id = int(id_text)
            except ValueError:
                id = None
            task = find(tasks, id)
            if task is None:
                print(f"no such task {id_text}")
            elif len(p_text) != 1 or p_text not in "0123456789":
                print(f"bad priority {p_text}")
            else:
                task.priority = int(p_text)
                print(f"prio {task.id} {task.priority}")
        elif command == "list":
            if rest == "all":
                for task in by_priority(tasks):
                    mark = "x" if task.done else "-"
                    print(f"{mark} {task.id} {task.title}")
            else:
                for task in by_priority(tasks):
                    if not task.done:
                        print(f"{task.id} {task.title}")
        else:
            print(f"? {command}")


main()

